<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue';
import { Button } from '../ui/button';
import { NumberInput } from '../ui/controls';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../ui/dialog';
import { criuStates, criuReasons, tlsStates, tlsReasons } from './environmentLabels';
import { runtimeRequest, type CpuResources, type EnvironmentFeature, type RuntimeEnvironment } from './runtimeApi';

/** 资源表单拥有冻结版本，列表轮询只更新摘要。 */
const props=defineProps<{environment:RuntimeEnvironment}>();
const emit=defineEmits<{refresh:[];busy:[value:boolean];cpu:[value:CpuResources]}>();
const cpu=ref<CpuResources|null>(null),cpus=ref<Record<'cli'|'sender'|'network',number|string>>({cli:'',sender:'',network:''});
const loading=ref(false),saving=ref(false),failed=ref(false),error=ref(''),message=ref('');
const feature=ref<{kind:'criu'|'content-capture';snapshot:EnvironmentFeature;enabled:boolean}|null>(null),featureLoading=ref(false),featureError=ref(''),featureFailed=ref(false),featureSaving=ref(false);
let alive=true,controller:AbortController|undefined,featureController:AbortController|undefined;
const roles=[{id:'cli',label:'CLI CPU'},{id:'sender',label:'发送器 CPU'},{id:'network',label:'网络 CPU'}] as const;
const kernelBusy=computed(()=>Object.values(props.environment.native_kernels??{'2.1.293':props.environment.native_kernel}).some(value=>['preparing','draining','switching','restoring','finishing','reconcile'].includes(value?.state??'')));
const locked=computed(()=>props.environment.busy||!['ready','stopped'].includes(props.environment.state)||kernelBusy.value||saving.value||featureSaving.value||featureLoading.value);
/** 重新读取实际配置后才允许重试，取消旧读请求。@return 读取结束。 */
async function load():Promise<void>{controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;error.value='';failed.value=false;try{const value=await runtimeRequest<CpuResources>(`/environments/${props.environment.environment_id}/cpu-resources`,{signal});if(!alive||signal.aborted)return;cpu.value=value;cpus.value={...value.cpus};emit('cpu',value);}catch(cause){if(alive&&!signal.aborted)error.value=(cause as Error).message;}finally{if(alive&&!signal.aborted)loading.value=false;}}
/** 仅提交页面读到的generation/revision，失败保留草稿。@return 保存结束。 */
async function saveCpu():Promise<void>{if(!cpu.value||saving.value||failed.value)return;const values=Object.fromEntries(roles.map(role=>[role.id,Number(cpus.value[role.id])]));if(roles.some(role=>cpus.value[role.id]===''||!Number.isFinite(values[role.id])||values[role.id]!<0.01||values[role.id]!>cpu.value!.host_cpus)){error.value='CPU额度需要在0.01与宿主核数之间';return;}saving.value=true;emit('busy',true);error.value='';message.value='';try{const value=await runtimeRequest<CpuResources>(`/environments/${props.environment.environment_id}/cpu-resources`,{method:'POST',body:{expected_generation:cpu.value.generation,expected_revision:cpu.value.revision,cpus:values}});if(!alive)return;cpu.value=value;cpus.value={...value.cpus};message.value='CPU 额度已应用，重建配置已保存。';emit('cpu',value);emit('refresh');}catch(cause){if(alive){failed.value=true;error.value=(cause as Error).message+'。请重新读取实际额度后再保存。';}}finally{if(alive){saving.value=false;emit('busy',false);}}}
/** 读取开关的独立冻结版本，用户确认后提交。@param kind 受控开关。@return 读取结束。 */
async function prepareFeature(kind:'criu'|'content-capture'):Promise<void>{if(locked.value)return;featureLoading.value=true;featureError.value='';featureFailed.value=false;featureController?.abort();featureController=new AbortController();const signal=featureController.signal;try{const value=await runtimeRequest<EnvironmentFeature>(`/environments/${props.environment.environment_id}/${kind}`,{signal});if(!alive||signal.aborted)return;feature.value={kind,snapshot:value,enabled:kind==='criu'&&value.applied===false?!!value.enabled:!value.enabled};}catch(cause){if(alive&&!signal.aborted)featureError.value=(cause as Error).message;}finally{if(alive&&!signal.aborted)featureLoading.value=false;}}
/** 应用用户确认的开关，失败后禁止重放旧版本。@return 提交结束。 */
async function saveFeature():Promise<void>{const value=feature.value;if(!value||featureSaving.value||featureFailed.value)return;featureSaving.value=true;emit('busy',true);try{await runtimeRequest(`/environments/${props.environment.environment_id}/${value.kind}`,{method:'POST',body:{enabled:value.enabled,expected_generation:value.snapshot.generation,expected_revision:value.snapshot.revision}});if(!alive)return;feature.value=null;message.value='设置已应用，实际状态随巡检更新。';emit('refresh');}catch(cause){if(alive){featureFailed.value=true;featureError.value=(cause as Error).message+'。请关闭后重新读取实际状态。';}}finally{if(alive){featureSaving.value=false;emit('busy',false);}}}
if(props.environment.isolation_version===2)void load();
onUnmounted(()=>{alive=false;controller?.abort();featureController?.abort();});
</script>
<template>
  <section class="environment-resource-editor">
    <form v-if="environment.isolation_version===2" @submit.prevent="saveCpu"><div class="runtime-section-title"><h4>CPU 额度</h4><span>{{ cpu?`宿主 ${cpu.host_cpus} 核 · 环境代次 ${cpu.generation}`:'正在核对实际额度' }}</span></div><p>分别调整 CLI、发送器和网络额度，保存后重建沿用。</p><div class="cpu-fields"><NumberInput v-for="role in roles" :key="role.id" v-model="cpus[role.id]" :label="role.label" :min="0.01" :max="cpu?.host_cpus" :step="0.01" required :disabled="loading||saving||!cpu||failed" /></div><p v-if="error" class="runtime-error" role="alert">{{ error }}</p><footer class="workspace-form-footer"><Button type="button" variant="outline" :disabled="loading||saving" @click="load">重新读取</Button><Button type="submit" :disabled="loading||saving||!cpu||failed">{{ saving?'正在应用…':'保存并应用' }}</Button></footer></form>
    <p v-else>此环境当前未提供独立 CPU 额度配置。</p>
    <div v-if="environment.platform!=='antigravity'" class="runtime-setting-row"><div><strong>CRIU 加速</strong><p>{{ typeof environment.criu?.enabled==='boolean'?(environment.criu.enabled?'自动开启':'手动关闭'):'选择待核对' }} · {{ criuStates[environment.criu?.state??'']||'状态待核对' }}</p><p v-if="environment.criu?.reason">{{ environment.request_backend==='native293'&&environment.criu.supported===false?'已选择原生运行时，等待环境准备':criuReasons[environment.criu.reason]||'状态待核对' }}<template v-if="environment.criu.reason==='memory_budget'"> · 当前 {{ environment.criu.memory_mib }} MiB，恢复需 {{ environment.criu.required_memory_mib }} MiB</template></p><p v-if="environment.criu?.last_start_source">最近扩容：{{ environment.criu.last_start_source==='criu_restore'?'CRIU 恢复':environment.criu.last_start_source==='exec'?'普通启动':'未观测' }}</p></div><button type="button" class="environment-switch" role="switch" aria-label="CRIU 加速" :aria-checked="environment.criu?.enabled===true" :disabled="locked||typeof environment.criu?.enabled!=='boolean'||!environment.criu?.supported||(!environment.criu.platform_enabled&&!environment.criu.enabled)" @click="prepareFeature('criu')"><span /></button></div>
    <div class="runtime-setting-row"><div><strong>请求内容采集</strong><p>{{ environment.content_capture?.applied?(environment.content_capture.enabled?'已开启':'已关闭'):'实际配置待核对' }} · 按账号保存请求内容</p><p v-if="environment.platform!=='antigravity'">原生 TLS 采集：{{ tlsStates[environment.content_capture?.tls_observer?.state??'']||'状态待核对' }} <template v-if="environment.content_capture?.tls_observer?.reason">· {{ tlsReasons[environment.content_capture.tls_observer.reason]||environment.content_capture.tls_observer.reason }}</template></p></div><button type="button" class="environment-switch" role="switch" aria-label="请求内容采集" :aria-checked="environment.content_capture?.enabled===true" :disabled="locked||!environment.content_capture?.supported||!environment.content_capture?.applied" @click="prepareFeature('content-capture')"><span /></button></div>
    <p v-if="featureLoading" role="status">正在读取实际配置…</p><p v-if="featureError&&!feature" class="runtime-error" role="alert">{{ featureError }}</p><p v-if="message" role="status">{{ message }}</p>
    <Dialog :open="!!feature" @update:open="value=>{if(!value&&!featureSaving)feature=null;}"><DialogContent @escape-key-down="event=>{if(featureSaving)event.preventDefault();}" @pointer-down-outside="event=>{if(featureSaving)event.preventDefault();}"><DialogHeader><DialogTitle>{{ feature?.enabled?'开启':'关闭' }}{{ feature?.kind==='criu'?'CRIU 加速':'请求内容采集' }}</DialogTitle><DialogDescription>{{ environment.name }} · 环境代次 {{ feature?.snapshot.generation }}。{{ feature?.kind==='criu'?'将在空闲时重建环境，保留 HOME 与账号身份。':'对后续请求生效。' }}</DialogDescription></DialogHeader><p v-if="featureError" role="alert" class="runtime-error">{{ featureError }}</p><div class="runtime-dialog-actions"><Button variant="outline" :disabled="featureSaving" @click="feature=null">取消</Button><Button :disabled="featureSaving||featureFailed||!feature?.snapshot.supported" @click="saveFeature">{{ featureSaving?'正在应用…':'确认应用' }}</Button></div></DialogContent></Dialog>
  </section>
</template>
